xml.Script:
        Colors[0] := 'FFFF00'; // Yellow 
        Colors[1] := 'FF0000'; // Red    
        Colors[2] := 'FF6000'; // Orange 
        Colors[3] := '008000'; // Green  
        Colors[4] := '0000A0'; // Blue   
        Colors[5] := '800080'; // Violett

        R := 0.9;
        H := R / sqrt(3);
        sAngle := 2 * Pi / 3;

        for i := 0 to 2 do begin
            A := sAngle * i;
            x[i] := R * sin(A);
            y[i] := R * cos(A);
            ax[i] :=-sin(A);
            ay[i] :=-cos(A);
            az[i] := sqrt(3)/2;
            ax[i + 3] := ax[i];
            ay[i + 3] := ay[i];
            az[i + 3] :=-az[i];
        end;

        A1 := ArcCos( 1/8);
        A2 := ArcCos(-3/4);

        D1 := R / 7 / sqrt(7);
        D2 := R / sqrt(7);

        delta := 0.001;
        RC := R * 0.2;
        DC := R * 2 / 7 * 1.005;
